package domain

// ChapterPlan is the chapter outline/plan generated by the Writer agent.
// Scene breakdown is no longer enforced; the Agent decides how to organize the content.
type ChapterPlan struct {
	Chapter    int             `json:"chapter"`
	Title      string          `json:"title"`
	Goal       string          `json:"goal"`
	Conflict   string          `json:"conflict"`
	Hook       string          `json:"hook"`
	EmotionArc string          `json:"emotion_arc,omitempty"`
	Notes      string          `json:"notes,omitempty"` // Agent's freeform notes
	Contract   ChapterContract `json:"contract,omitempty"`
}

// ChapterContract is the chapter acceptance contract shared between Writer and Editor.
// It defines progress points that must be completed, boundaries that must not be crossed, and review focus areas.
type ChapterContract struct {
	RequiredBeats    []string `json:"required_beats,omitempty"`    // Progress items that must happen in this chapter
	ForbiddenMoves   []string `json:"forbidden_moves,omitempty"`   // Moves that explicitly must not happen in this chapter
	ContinuityChecks []string `json:"continuity_checks,omitempty"` // Continuity points to verify specifically in this chapter
	EvaluationFocus  []string `json:"evaluation_focus,omitempty"`  // Points the Editor needs to pay close attention to
	EmotionTarget    string   `json:"emotion_target,omitempty"`    // Optional: primary emotion intended for readers to feel
	PayoffPoints     []string `json:"payoff_points,omitempty"`     // Optional: key plot payoff/payback points in critical chapters
	HookGoal         string   `json:"hook_goal,omitempty"`         // Optional: reading desire driven by the chapter end hook
}

// ChapterSummary represents chapter summary used by the context window of subsequent chapters.
type ChapterSummary struct {
	Chapter    int      `json:"chapter"`
	Title      string   `json:"title"`
	Summary    string   `json:"summary"`
	Characters []string `json:"characters"`
	KeyEvents  []string `json:"key_events"`
}

// ArcSummary represents arc-level summary, generated by Editor when an arc ends.
type ArcSummary struct {
	Volume    int      `json:"volume"`
	Arc       int      `json:"arc"`
	Title     string   `json:"title"`
	Summary   string   `json:"summary"`
	KeyEvents []string `json:"key_events"`
}

// VolumeSummary represents volume-level summary, generated when a volume ends.
type VolumeSummary struct {
	Volume    int      `json:"volume"`
	Title     string   `json:"title"`
	Summary   string   `json:"summary"`
	KeyEvents []string `json:"key_events"`
}

// CharacterSnapshot represents character state snapshot, recorded at arc boundaries.
type CharacterSnapshot struct {
	Volume     int    `json:"volume"`
	Arc        int    `json:"arc"`
	Name       string `json:"name"`
	Status     string `json:"status"`
	Power      string `json:"power,omitempty"`
	Motivation string `json:"motivation"`
	Relations  string `json:"relations,omitempty"`
}

// OutlineFeedback is the Writer's feedback on the outline, optional when submitting a chapter.
type OutlineFeedback struct {
	Deviation  string `json:"deviation"`  // Description of deviation
	Suggestion string `json:"suggestion"` // Adjustment suggestion
}

// WritingStyleRules representations of writing style rules extracted from written chapters, generated by Editor at arc boundaries.
// Replaces raw text samples with rules instead of carrying raw text fragments.
type WritingStyleRules struct {
	Volume    int              `json:"volume"`
	Arc       int              `json:"arc"`
	Prose     []string         `json:"prose"`      // 3-5 prose style rules, each ≤50 chars
	Dialogue  []CharacterVoice `json:"dialogue"`   // Character dialogue style rules
	Taboos    []string         `json:"taboos"`     // Taboo checklist
	UpdatedAt string           `json:"updated_at"` // ISO8601 timestamp
}

// CharacterVoice represents dialogue style rules for a single character.
type CharacterVoice struct {
	Name  string   `json:"name"`
	Rules []string `json:"rules"` // 2-3 speech trait rules, each ≤30 chars
}

// RelatedChapter represents a recommended historical chapter for re-reading.
type RelatedChapter struct {
	Chapter int    `json:"chapter"`
	Reason  string `json:"reason"`
}

// RecallItem represents long-term information selectively recalled based on the current task.
// Does not replace formal artifacts, only responsible for injecting a small amount of relevant historical information back to the model.
type RecallItem struct {
	Kind    string `json:"kind"`
	Key     string `json:"key,omitempty"`
	Chapter int    `json:"chapter,omitempty"`
	Reason  string `json:"reason,omitempty"`
	Summary string `json:"summary,omitempty"`
}

// CommitResult is the structured return value of the commit_chapter tool.
// Contains only factual fields; "what to do next" is generated by the Reminder channel based on the current Progress.
type CommitResult struct {
	Chapter        int              `json:"chapter"`
	Committed      bool             `json:"committed"`
	WordCount      int              `json:"word_count"`
	NextChapter    int              `json:"next_chapter"`
	ReviewRequired bool             `json:"review_required"`
	ReviewReason   string           `json:"review_reason,omitempty"`
	HookType       string           `json:"hook_type,omitempty"`
	DominantStrand string           `json:"dominant_strand,omitempty"`
	Feedback       *OutlineFeedback `json:"feedback,omitempty"`
	// Long-form stratification signals
	ArcEnd         bool `json:"arc_end,omitempty"`
	VolumeEnd      bool `json:"volume_end,omitempty"`
	Volume         int  `json:"volume,omitempty"`
	Arc            int  `json:"arc,omitempty"`
	NeedsExpansion bool `json:"needs_expansion,omitempty"`  // Next arc is skeleton, needs expansion
	NeedsNewVolume bool `json:"needs_new_volume,omitempty"` // Needs Architect to create next volume
	NextVolume     int  `json:"next_volume,omitempty"`      // Next volume sequence number
	NextArc        int  `json:"next_arc,omitempty"`         // Next arc sequence number
	// Completion fact: whether the entire book is complete after this commit
	BookComplete bool `json:"book_complete,omitempty"`
	// Flow is the current snapshot of Progress.Flow (writing / reviewing / rewriting / polishing)
	Flow string `json:"flow,omitempty"`
}
